import mongoose from 'mongoose';
const { Schema } = mongoose;

const loginEventSchema = new Schema({
  user: { type: Schema.Types.ObjectId, ref: 'User', default: null },
  email: { type: String, required: true, lowercase: true, trim: true },
  success: { type: Boolean, required: true },
  reason: { type: String, enum: ['ok', 'bad_password', 'unknown_user', 'account_locked'], default: 'ok' },
  ip: { type: String, required: true },
  userAgent: { type: String, default: '' },
  location: { country: { type: String }, city: { type: String } },
  // "simulated" = generated by our test/simulation tools. "application" = real logins to this app.
  source: { type: String, enum: ['application', 'simulated'], default: 'application' },
  timestamp: { type: Date, default: Date.now },
});

loginEventSchema.index({ email: 1, timestamp: -1 });
loginEventSchema.index({ ip: 1, timestamp: -1 });

export const LoginEvent = mongoose.model('LoginEvent', loginEventSchema);